        GCTLevelAddMERGE_CELL_M(builder, self.MERGE_CELL_M)
        GCTLevelAddDERIVATION(builder, self.DERIVATION)
        GCTLevelAddENCODING(builder, self.ENCODING)
        if self.CHUNK_CID is not None:
            GCTLevelAddCHUNK_CID(builder, CHUNK_CID)
        GCTLevelAddCHUNK_BYTE_LENGTH(builder, self.CHUNK_BYTE_LENGTH)
        if self.CENTERS is not None:
            GCTLevelAddCENTERS(builder, CENTERS)
        if self.SIGMAS is not None:
            GCTLevelAddSIGMAS(builder, SIGMAS)
        if self.BOUNDARY is not None:
            GCTLevelAddBOUNDARY(builder, BOUNDARY)
        if self.FINE_NORMAL is not None:
            GCTLevelAddFINE_NORMAL(builder, FINE_NORMAL)
        if self.OPTICAL_DEPTH_POS is not None:
            GCTLevelAddOPTICAL_DEPTH_POS(builder, OPTICAL_DEPTH_POS)
        if self.OPTICAL_DEPTH_NEG is not None:
            GCTLevelAddOPTICAL_DEPTH_NEG(builder, OPTICAL_DEPTH_NEG)
        GCTLevel = GCTLevelEnd(builder)
        return GCTLevel
